import React, { useState } from "react";
import { useNavigate } from "react-router-dom"; // To navigate to other pages after successful login/register

const AuthPage = () => {
  const [isLogin, setIsLogin] = useState(true); // Toggle between login and register
  const [formData, setFormData] = useState({ username: "", password: "" });
  const [error, setError] = useState("");
  const navigate = useNavigate(); // Hook to navigate to different pages

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({ ...prevData, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.password.length !== 6) {
      setError("Password must be exactly 6 characters long.");
      return;
    }

    // Simulate authentication (you can connect this to a backend API)
    if (isLogin) {
      // Logic for login (e.g., compare username and password with the server)
      // For now, we'll just assume successful login.
      setError("");
      navigate("/predict"); // Redirect to prediction page on successful login
    } else {
      // Logic for registration (e.g., save user to the database)
      // For now, we'll just assume successful registration.
      setError("");
      navigate("/predict"); // Redirect to prediction page after successful registration
    }
  };

  return (
    <div style={{ padding: "2rem", fontFamily: "Arial", maxWidth: "400px", margin: "auto" }}>
      <h2>{isLogin ? "Login" : "Register"}</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>
            Username:
            <input
              type="text"
              name="username"
              value={formData.username}
              onChange={handleChange}
              required
            />
          </label>
        </div>
        <div>
          <label>
            Password:
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </label>
        </div>
        {error && <div style={{ color: "red", marginTop: "1rem" }}>{error}</div>}
        <div style={{ marginTop: "1rem" }}>
          <button type="submit">{isLogin ? "Login" : "Register"}</button>
        </div>
      </form>
      <div style={{ marginTop: "1rem" }}>
        <button onClick={() => setIsLogin(!isLogin)}>
          {isLogin ? "Need an account? Register here" : "Already have an account? Login"}
        </button>
      </div>
    </div>
  );
};

export default AuthPage;
